(function(){
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
 const getState=()=>{try{return JSON.parse(localStorage.getItem('nawaf-hq-v3')||'null')}catch{return null}};
 function clickText(text){const el=$$('button').find(b=>b.textContent.includes(text));if(el){el.click();return true}return false}
 function addCommandDock(){if($('#hq-command-dock'))return;const main=$('.main');if(!main)return;const dock=document.createElement('section');dock.id='hq-command-dock';dock.className='hq-command-dock card';dock.innerHTML='<div class="dock-copy"><span class="eyebrow">CEO COMMAND CENTER</span><b>وش تبغى الشركة تسوي الآن؟</b><small>أي نشاط يبدأ من توجيهك، وما يظهر إنجاز بدون دليل.</small></div><div class="dock-actions"><button id="hq-start-command" class="primary">✦ أعطِ توجيهًا للشركة</button><button id="hq-open-board">◎ افتح مجلس الشركة</button></div>';$('.greeting')?.insertAdjacentElement('afterend',dock);$('#hq-start-command').onclick=()=>typeof window.NawafHQ?.commandView==='function'?window.NawafHQ.commandView():clickText('بسم الله')||clickText('توجيه الشركة')||$('#manager-core')?.click();$('#hq-open-board').onclick=()=>window.NawafCompanyBoard?.open?.('company')||clickText('مجلس الشركة')}
 function statusLabel(x){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',COLLABORATING:'يتعاون',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظار نواف'})[x]||x||'جاهز'}
 function person(s,id,fallback,role){const e=(s?.employees||[]).find(x=>x.id===id)||{};return {id,name:e.name||fallback,role:e.role||role,status:e.status||'READY',task:e.currentTask||e.task||''}}
 function openPerson(id){const s=getState(),e=(s?.employees||[]).find(x=>x.id===id);if(typeof window.NawafHQ?.employeeView==='function')return window.NawafHQ.employeeView(id);const old=$(`.robot[data-id="${id}"]`)||$(`.robot[data-employee="${id}"]`);if(old)return old.click();if(id==='sara')window.NawafCompanyBoard?.open?.('company')}
 function buildOffice(){const office=$('.office');if(!office||office.dataset.hqBuilt==='1')return;office.dataset.hqBuilt='1';office.classList.add('hq-office-v3');const s=getState();const people=[person(s,'sara','سارة','المدير العام AI'),person(s,'omar','عمر','التقنية والبحث'),person(s,'lian','ليان','المنتج والتجربة'),person(s,'noura','نورة','الجودة والمراجعة')];office.innerHTML=`<div class="ops-shell"><header class="ops-head"><div><span class="ops-live"><i></i> NAWAF HQ LIVE</span><h2>مركز عمليات الشركة</h2><p>المقر يعكس حالة العمل المسجلة فعليًا</p></div><button class="ops-council">مجلس الشركة</button></header><div class="ops-floor"><div class="ops-grid"></div><section class="dept tech"><span>TECH & RESEARCH</span><b>التقنية والبحث</b></section><section class="dept product"><span>PRODUCT & UX</span><b>المنتج والتجربة</b></section><section class="dept quality"><span>QUALITY</span><b>الجودة والمراجعة</b></section><section class="dept command"><span>GENERAL MANAGEMENT</span><b>الإدارة العامة</b></section><div class="command-table"><div class="hq-mark">N</div><small>COMMAND CORE</small></div>${people.map((p,i)=>`<button class="agent agent-${p.id} state-${p.status.toLowerCase()}" data-agent="${p.id}"><span class="agent-orb"><i></i></span><span class="agent-copy"><b>${p.name}</b><small>${p.role}</small></span><em>${statusLabel(p.status)}</em></button>`).join('')}<div class="ops-path path-a"></div><div class="ops-path path-b"></div></div><footer class="ops-footer"><span><i></i> العمل الموثّق فقط</span><small>اضغط على أي موظف لفتح مساحة عمله</small></footer></div>`;$('.ops-council',office).onclick=()=>window.NawafCompanyBoard?.open?.('company')||clickText('مجلس الشركة');$$('[data-agent]',office).forEach(b=>b.onclick=()=>openPerson(b.dataset.agent))}
 function fixBrand(){const b=$('.brand');if(b)b.innerHTML='NAWAF <span>HQ</span><small>AI COMPANY OS</small>';document.title='NAWAF HQ — لوحة القيادة'}
 function addTruthStatus(){if($('#truth-status'))return;const top=$('.topbar');if(!top)return;const x=document.createElement('div');x.id='truth-status';x.className='truth-status';x.innerHTML='<i></i><span>وضع العمل الموثّق</span><small>لا نشاط وهمي</small>';top.appendChild(x)}
 function addQuickProjectLabels(){$$('.project').forEach(p=>{const n=$('b',p)?.textContent?.trim();if(n&&!$('.project-kind',p)){const t=document.createElement('small');t.className='project-kind';t.textContent=n==='قدّها'?'مشروع الألعاب':n==='مُعِين'?'التطبيق الإسلامي':'مشروع';p.querySelector('span')?.appendChild(t)}})}
 function boot(){fixBrand();addCommandDock();buildOffice();addTruthStatus();addQuickProjectLabels()}
 const mo=new MutationObserver(()=>{clearTimeout(window.__hqEnhance);window.__hqEnhance=setTimeout(boot,60)});mo.observe(document.documentElement,{childList:true,subtree:true});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();